project_task.solution:
// shipName, stars ve lives değişkenlerini oluştur
const shipName = "Kartal";
let stars = 0;
let lives = 3;

console.log("Gemi:", shipName, "| Yıldız:", stars, "| Can:", lives);

check.js:
assert(typeof shipName === "string" && shipName.trim() !== "", "shipName boş olmayan bir metin olmalı.");
assert(stars === 0 && lives === 3, "stars 0, lives 3 olmalı.");
assert(_lines.includes(`Gemi: ${shipName} | Yıldız: 0 | Can: 3`), "Durum satırı çıktıda görünmeli.");

